import { collection, addDoc, query, where, orderBy, limit, getDocs, getDoc, doc, serverTimestamp } from 'firebase/firestore';
import { db } from './firebase';

/**
 * Tombala oyunu için istatistik gönder
 */
export async function postTombalaStats({ userId, score, cardsMatched = 0, duration = 0 }: { userId: string; score: number; cardsMatched?: number; duration?: number; }) {
  const data = { userId, score, cardsMatched, duration, playedAt: serverTimestamp() };
  const colRef = collection(db, 'tombalaStats');
  const docRef = await addDoc(colRef, data);
  return { id: docRef.id, ...data };
}

/**
 * Tombala leaderboard (en yüksek skor) getirir
 */
export async function getTombalaLeaderboard() {
  const q = query(
    collection(db, 'tombalaStats'),
    orderBy('score', 'desc'),
    limit(10)
  );
  const snap = await getDocs(q);
  const results = [] as Array<{ userId: string; name: string; score: number }>
  for (const docSnap of snap.docs) {
    const data: any = docSnap.data();
    // Kullanıcı profili için users koleksiyonundan isim al
    let name = data.userId;
    try {
      const userDoc = await getDoc(doc(db, 'users', data.userId));
      if (userDoc.exists()) {
        const u = userDoc.data();
        name = u.displayName || u.username || data.userId;
      }
    } catch (e) {
      console.error('Error fetching user for leaderboard:', e);
    }
    results.push({ userId: data.userId, name, score: data.score });
  }
  return results;
}

/**
 * Tombala achievements: kullanıcıya ait kazanılan başarımları hesaplar
 */
export async function getTombalaAchievements(userId: string) {
  // Tüm kullanıcıya ait istatistikleri çek
  const snap = await getDocs(query(
    collection(db, 'tombalaStats'),
    where('userId', '==', userId)
  ));
  const stats = snap.docs.map(docSnap => docSnap.data());
  const count = stats.length;
  const scores = stats.map(s => (s as any).score);

  const achievements = [] as Array<{ id: string; title: string; unlockedAt: any }>
  const now = serverTimestamp();

  if (count >= 1) {
    achievements.push({ id: 'first_game', title: 'İlk Tombala Oyunu', unlockedAt: now });
  }
  if (count >= 10) {
    achievements.push({ id: 'ten_games', title: '10 Tombala Oyunu', unlockedAt: now });
  }
  const maxScore = scores.length ? Math.max(...scores) : 0;
  if (maxScore >= 100) {
    achievements.push({ id: 'score_100', title: '100 Puan Üstü Skor', unlockedAt: now });
  }
  if (maxScore >= 500) {
    achievements.push({ id: 'score_500', title: '500 Puan Üstü Skor', unlockedAt: now });
  }
  return achievements;
} 